<?php require_once __DIR__.'/includes/functions.php';$items=cart();$products=get_products(array_keys($items));$subtotal=0;foreach($items as $id=>$item)if(isset($products[$id]))$subtotal+=$products[$id]['price']*$item['qty'];$title='حقيبتي | ALAN';include __DIR__.'/includes/header.php';?><div class="page"><div class="page-title"><p class="eyebrow">حقيبتي</p><h1>اختياراتكِ الجميلة</h1></div><?php if(!$products):?><div class="empty">حقيبتكِ فارغة الآن.<br><br><a class="btn" href="<?=base('shop.php')?>">ابدئي التسوق</a></div><?php else:?><div class="cart-layout"><div><?php foreach($items as $id=>$item):if(!isset($products[$id]))continue;$p=$products[$id];?><div class="cart-row"><img src="<?=e(product_image($p))?>" alt="<?=e($p['name'])?>"><div class="row-info"><strong><?=e($p['name'])?></strong><p><?=e($p['color'])?> · <?=e($p['sizes'])?></p><form method="post" action="<?=base('api/orders.php?action=update-cart')?>"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="product_id" value="<?=$id?>"><input type="number" name="qty" value="<?=$item['qty']?>" min="0"><button class="link">تحديث</button></form></div><strong><?=money($p['price']*$item['qty'])?></strong></div><?php endforeach;?></div><aside class="summary"><h3>ملخص الطلب</h3><div><span>المجموع الفرعي</span><span><?=money($subtotal)?></span></div><div><span>الشحن</span><span>يُحسب عند العنوان</span></div><div class="total"><span>الإجمالي</span><span><?=money($subtotal)?></span></div><a class="btn" href="<?=base('checkout.php')?>">إتمام الطلب</a></aside></div><?php endif;?></div><?php include __DIR__.'/includes/footer.php';?>
